64	     * 关闭实验；仅 OPEN 时生效，返回受影响行数。
65	     */
66	    public int markClosed(String experimentId) {
67	        return jdbc.update("UPDATE experiment SET status = 'CLOSED' WHERE id = ? AND status = 'OPEN'",
68	                experimentId);
